<script setup>
import { BookOpenCheck, MapPin } from '@lucide/vue';
import { onMounted, ref, watch } from 'vue';
import StatusPill from '../../components/ui/StatusPill.vue';
import { api } from '../../services/api.js';
const bookings=ref([]),status=ref(''),rideType=ref(''),loading=ref(true);let timer;
async function load(){loading.value=true;try{const response=await api.get('/admin/bookings',{params:{status:status.value||undefined,rideType:rideType.value||undefined,limit:50}});bookings.value=response.data.data}finally{loading.value=false}}watch([status,rideType],()=>{clearTimeout(timer);timer=setTimeout(load,150)});onMounted(load);
const format=(value)=>new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Manila'}).format(new Date(value));
</script>
<template><section class="page admin-page"><div class="page-header"><div><span class="eyebrow">Operations log</span><h1 class="page-title">Booking management</h1><p class="muted">Monitor every passenger booking and its assigned driver.</p></div></div><div class="filters card"><select v-model="status"><option value="">All statuses</option><option v-for="item in ['searching','accepted','driver_arriving','picked_up','completed','cancelled','expired']" :key="item" :value="item">{{ item.replaceAll('_',' ') }}</option></select><select v-model="rideType"><option value="">All ride types</option><option value="shared">Shared</option><option value="non_shared">Private</option></select></div><div v-if="loading" class="skeleton" style="height:350px"></div><div v-else-if="!bookings.length" class="card empty-state"><div><BookOpenCheck :size="38" /><p>No bookings match these filters.</p></div></div><div v-else class="table-card card"><table><thead><tr><th>Booking</th><th>Commuter</th><th>Route</th><th>Driver</th><th>Fare</th><th>Status</th></tr></thead><tbody><tr v-for="item in bookings" :key="item._id"><td><strong>#{{ item._id.slice(-6).toUpperCase() }}</strong><small>{{ format(item.createdAt) }} · {{ item.rideType==='shared'?'Shared':'Private' }}</small></td><td>{{ item.commuterId?.firstName }} {{ item.commuterId?.lastName }}</td><td><span class="route"><MapPin :size="14" />{{ item.pickupLocation.label }} → {{ item.dropoffLocation.label }}</span></td><td>{{ item.assignedDriverId?.userId ? `${item.assignedDriverId.userId.firstName} ${item.assignedDriverId.userId.lastName}` : 'Unassigned' }}</td><td>₱{{ (item.finalFare??item.estimatedFare).toFixed(0) }}</td><td><StatusPill :status="item.status" /></td></tr></tbody></table></div></section></template>
<style scoped>.admin-page{max-width:1300px}.filters{display:flex;gap:10px;padding:12px;margin-bottom:15px}.filters select{height:41px;padding:0 12px;border:1px solid var(--color-border);border-radius:11px;background:white;text-transform:capitalize}.table-card{overflow-x:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{padding:13px 14px;border-bottom:1px solid var(--color-border);font-size:.72rem;text-align:left}th{color:var(--color-text-soft);font-size:.63rem;text-transform:uppercase}td:first-child{display:grid;gap:3px}td:first-child small{color:var(--color-text-soft);font-size:.62rem}.route{display:flex;max-width:260px;align-items:center;gap:5px;overflow:hidden;text-overflow:ellipsis}.route svg{flex:0 0 auto;color:var(--color-primary)}.empty-state svg{margin:auto auto 10px;color:var(--color-primary)}</style>

